  ["Each node links to the next one. Fill the field type: Next ___"] = "Každý uzel odkazuje na další. Doplň typ pole: Next ___",
  ["Eight letters: every goroutine waits on every other. The send never returns."] = "Osm písmen: každá goroutine čeká na všechny ostatní. Odeslání se nikdy nevrátí.",
  ["Empty brackets then the element type. [3]int would be an array."] = "Prázdné hranaté závorky a pak typ prvku. [3]int by bylo pole.",
  ["Empty parentheses. go needs a call, not just a function value."] = "Prázdné závorky. go potřebuje volání, ne jen hodnotu funkce.",
  ["Empty the whole map in one call (Go 1.21). Which built-in?"] = "Vyprázdni celou mapu jedním voláním (Go 1.21). Která vestavěná funkce?",
  ["Errors and defer"] = "Chyby a defer",
  ["Errors: New, wrap, Is, As"] = "Chyby: New, wrap, Is, As",
  ["Every Go file starts with package. import brings other packages in."] = "Každý soubor v Go začíná package. import přináší další balíčky.",
  ["Every key of the price map, as an iterator (Go 1.23). Fill: maps.___(prices)"] = "Každý klíč mapy cen jako iterátor (Go 1.23). Doplň: maps.___(prices)",
  ["Every one of these is 'use a map' or 'use two pointers'. Pick the right one."] = "Každá z nich je 'použij mapu' nebo 'použij dva ukazatele'. Vyber správně.",
  ["Every recursion stops somewhere. fact(0) and fact(1) return what?"] = "Každá rekurze se někde zastaví. Co vrací fact(0) a fact(1)?",
  ["Every runnable Go program lives in which package?"] = "Ve kterém balíčku žije každý spustitelný program v Go?",
  ["Everything from index 1 to the end. A slice expression, no copy."] = "Vše od indexu 1 do konce. Výraz slice, bez kopie.",
  ["F for a file or writer, then printf. The writer is the first argument."] = "F jako file nebo writer, pak printf. Writer je první argument.",
  ["FINAL  -  the kitchen"] = "FINÁLE  -  kuchyně",
  ["FULL"] = "CELÁ",
  ["Find suspicious code the compiler allows: wrong Printf verbs, copied locks. Fill: go ___ ./..."] = "Najdi podezřelý kód, který kompilátor pustí: špatné verby Printf, kopírované zámky. Doplň: go ___ ./...",
  ["Five letters. Also ends a switch or select case early."] = "Pět písmen. Předčasně ukončí i case ve switch nebo select.",
  ["Five letters. On a slice it zeroes every element instead."] = "Pět písmen. Na slice místo toho vynuluje každý prvek.",
  ["Five letters. Return an error for expected failure; this is for the impossible."] = "Pět písmen. Na očekávané selhání vrať error; tohle je pro nemožné.",
  ["Five letters. go run compiles and runs; this one only compiles."] = "Pět písmen. go run kompiluje a spouští; tohle jen kompiluje.",
  ["Fix the Go bugs. Get the morning set."] = "Oprav bugy v Go. Získej ranní menu.",
  ["Floor 8. Type the floor. Don't hard-code magic."] = "Patro 8. Napiš patro. Žádná magická čísla natvrdo.",
  ["Floor is a named type over int. Convert the int 3 into a Floor. Fill: f := ___(3)"] = "Floor je pojmenovaný typ nad int. Převeď int 3 na Floor. Doplň: f := ___(3)",
  ["Floyd: fast moves two steps per turn. Fill: fast = fast.Next.___"] = "Floyd: fast dělá dva kroky na tah. Doplň: fast = fast.Next.___",
  ["Followed by the value, then case labels. No break needed."] = "Za ním hodnota, pak návěští case. break není potřeba.",
  ["Four letters, a Greek one. Resets to 0 in every const block, +1 per line."] = "Čtyři písmena, řecké písmeno. V každém bloku const začíná od 0, +1 na řádek.",
  ["Four letters, capital K. slices.Sorted(maps.Keys(m)) gives a sorted slice."] = "Čtyři písmena, velké K. slices.Sorted(maps.Keys(m)) dá seřazený slice.",
  ["Four letters, capital O. Its only method is Do."] = "Čtyři písmena, velké O. Jediná metoda je Do.",
  ["Four letters, capital S. SortFunc takes a compare function."] = "Čtyři písmena, velké S. SortFunc bere porovnávací funkci.",
  ["Four letters. An alias of int32. byte is the alias of uint8."] = "Čtyři písmena. Alias pro int32. byte je alias pro uint8.",
  ["Four letters. Every file may have one; the runtime calls it for you."] = "Čtyři písmena. Každý soubor ji může mít; runtime ji zavolá za tebe.",
  ["Four letters. It also builds maps and channels."] = "Čtyři písmena. Vytváří i mapy a kanály.",
  ["Four letters: make it neat. Run it before every commit."] = "Čtyři písmena: udělej pořádek. Spouštěj před každým commitem.",
  ["Four quests: BASIC, ADVANCED, DELIVERY, CODE RUSH. Q switches."] = "Čtyři mise: ZÁKLADY, POKROČILÉ, ROZVOZ, CODE RUSH. Q přepíná.",
  ["Fprintf writes to any io.Writer: files, buffers, network, ResponseWriter."] = "Fprintf píše do jakéhokoli io.Writer: soubory, buffery, síť, ResponseWriter.",
  ["From m to the end. a[:m] and a[m:] cover the slice exactly once."] = "Od m do konce. a[:m] a a[m:] pokryjí slice přesně jednou.",
  ["Functions and returns"] = "Funkce a návratové hodnoty",
  ["Generics, embedding, closures"] = "Generika, embedding, closures",
  ["Give up after one second. Fill: case <-time.___(time.Second)"] = "Vzdej to po jedné sekundě. Doplň: case <-time.___(time.Second)",
  ["Gives index and value. The blank _ throws the index away."] = "Dává index a hodnotu. Prázdný _ index zahodí.",
  ["Go + routine. Not a full OS thread. The scheduler parks them."] = "Go + routine. Ne plné vlákno OS. Plánovač je uspává.",
  ["Go 1.21-1.23: slices, maps, min, iterators"] = "Go 1.21-1.23: slices, maps, min, iterátory",
  ["Go 1.22 loops over a plain number. Fill: for i := ___ 3"] = "Go 1.22 iteruje přes obyčejné číslo. Doplň: for i := ___ 3",
  ["Go has no set type; a map to this type is the idiom. struct{} also works."] = "Go nemá typ množiny; idiomem je mapa na tento typ. struct{} funguje také.",
  ["Go has no while. Which keyword loops while i < 8?"] = "Go nemá while. Které klíčové slovo cyklí, dokud i < 8?",
  ["Go has one loop: for. if needs no parentheses. range walks a slice."] = "Go má jeden cyklus: for. if nepotřebuje závorky. range projde slice.",
  ["Go never converts numbers silently. Type name, then parentheses. 64-bit float."] = "Go nikdy nepřevádí čísla potichu. Název typu a pak závorky. 64bitový float.",
  ["Go never leaves a variable uninitialized. Numbers start here."] = "Go nikdy nenechá proměnnou neinicializovanou. Čísla začínají tady.",
  ["Goroutines"] = "Goroutiny",
  ["Group name and price in one type. Which keyword?"] = "Seskup jméno a cenu do jednoho typu. Které klíčové slovo?",
  ["Grow a slice by one hash brown. Which built-in?"] = "Zvětši slice o jeden hash brown. Která vestavěná funkce?",
  ["HERE"] = "TADY",
  ["HIDE"] = "SKRÝT",
  ["HINT"] = "TIP",
  ["Half-open [lo, hi): loop while lo < hi, no off-by-one."] = "Polootevřený [lo, hi): smyčka dokud lo < hi, žádná chyba o jedničku.",
  ["Halve the gap. (lo+hi)/2 can overflow in other languages; this form never does."] = "Rozpůl mezeru. (lo+hi)/2 může v jiných jazycích přetéct; tento tvar nikdy.",
  ["Hand both values back to the caller. Which keyword?"] = "Vrať obě hodnoty volajícímu. Které klíčové slovo?",
  ["Handle + Func. Plain Handle takes an http.Handler value instead."] = "Handle + Func. Samotné Handle bere místo toho hodnotu http.Handler.",
  ["HandleFunc maps a path to func(w, r). Fprintf(w) replies. ListenAndServe runs."] = "HandleFunc mapuje cestu na func(w, r). Fprintf(w) odpoví. ListenAndServe běží.",
  ['HandleFunc registers on the default mux. Go 1.22 routes can say "GET /order/{id}".'] = 'HandleFunc registruje na výchozím muxu. Cesty v Go 1.22 umí "GET /order/{id}".',
  ["Hash brown on one burner. Muffin on another. Both at once."] = "Hash brown na jednom hořáku. Muffin na druhém. Obojí naráz.",
  ["Have we seen the partner of x? Fill the lookup: seen[target-x]"] = "Viděli jsme partnera x? Doplň vyhledání: seen[target-x]",
  ["Height is one plus the taller subtree. Fill: 1 + max(height(n.Left), height(n.___))"] = "Výška je jedna plus vyšší podstrom. Doplň: 1 + max(height(n.Left), height(n.___))",
  ["How many items are in the slice right now? Which built-in?"] = "Kolik položek je teď ve slice? Která vestavěná funkce?",
  ["How many items fit before append must reallocate? Which built-in?"] = "Kolik položek se vejde, než append musí realokovat? Která vestavěná funkce?",
  ["If the guest leaves, cancel. The fryer stops."] = "Když host odejde, zruš. Fritéza se zastaví.",
  ["If there is a loop the fast runner laps the slow one. O(1) memory."] = "Pokud je tam smyčka, rychlý běžec dohoní pomalého o kolo. Paměť O(1).",
  ["In real code: sort a slice of structs by price. Fill: sort.___(orders, func(i, j int) bool {...})"] = "V reálném kódu: seřaď slice structů podle ceny. Doplň: sort.___(orders, func(i, j int) bool {...})",
  ["In-order on a BST yields sorted output. Pre-order: node first. Post-order: node last."] = "In-order na BST dává seřazený výstup. Pre-order: uzel první. Post-order: uzel poslední.",
  ["Increment a counter without a mutex. Which package? ___.AddInt64(&count, 1)"] = "Zvyš čítač bez mutexu. Který balíček? ___.AddInt64(&count, 1)",
  ["Is ErrCold anywhere in that chain? Fill: errors.___(err, ErrCold)"] = "Je ErrCold někde v tom řetězu? Doplň: errors.___(err, ErrCold)",
  ['Is muffin on the list? Fill: slices.___(names, "muffin")'] = 'Je muffin na seznamu? Doplň: slices.___(names, "muffin")',
  ["It closes over n. Inner func, outer variable."] = "Uzavírá do sebe n. Vnitřní func, vnější proměnná.",
  ["It runs on your laptop. Make it build on the shop's machine."] = "Na tvém notebooku to běží. Ať se to sestaví i na počítači v obchodě.",
  ["Jumps to the next iteration. break would leave the loop entirely."] = "Skočí na další iteraci. break by cyklus úplně opustil.",
  ["Keyword chan, then the element type. make allocates it."] = "Klíčové slovo chan, pak typ prvku. make ho alokuje.",
  ["Kitchen should gain Grill's methods without wrapping. Put Grill where?"] = "Kitchen má získat metody Grill bez obalování. Kam dát Grill?",
  ["Know the algorithm for the whiteboard, use the library in production."] = "Znej algoritmus na tabuli, v produkci použij knihovnu.",
  ["LAND"] = "ŠÍŘKA",
  ["Leave note out of the JSON when it is empty. Fill the tag option."] = "Když je note prázdné, vynech ho z JSON. Doplň volbu tagu.",
  ["Like %v, but with w for wrap. errors.Unwrap gets the inner error back."] = "Jako %v, ale s w jako wrap. errors.Unwrap vrátí vnitřní error.",
  ["Like fmt.Errorf but on t. Fatalf would stop this test at once."] = "Jako fmt.Errorf, ale na t. Fatalf by tento test hned zastavil.",
  ["Linked list: reverse, cycle"] = "Zřetězený seznam: otočení, cyklus",
  ["Listen, And, Serve. Returns only on error, hence log.Fatal."] = "Listen, And, Serve. Vrací se jen při chybě, proto log.Fatal.",
  ["ListenAndServe blocks forever. Every request runs in its own goroutine."] = "ListenAndServe blokuje navždy. Každý požadavek běží ve vlastní goroutine.",
  ["Lock a shared counter. Fill the type: var mu sync.___"] = "Zamkni sdílený čítač. Doplň typ: var mu sync.___",
  ["Lock; defer Unlock is the pattern. A forgotten Unlock deadlocks the next caller."] = "Lock; defer Unlock je ten vzor. Zapomenutý Unlock zablokuje dalšího volajícího.",
  ["Looks like switch, but every case is a channel send or receive."] = "Vypadá jako switch, ale každý case je odeslání nebo příjem z kanálu.",
  ["Lucky Mac  ·  Causeway Bay"] = "Lucky Mac  ·  Causeway Bay",
  ["Lucky Mac  ·  delivery app"] = "Lucky Mac  ·  rozvozová aplikace",
  ["Lucky Mac  ·  the morning set"] = "Lucky Mac  ·  ranní menu",
  ["Lucky Mac is found. Leave the loop right now. Which keyword?"] = "Lucky Mac je nalezen. Opusť cyklus hned teď. Které klíčové slovo?",
  ["Lucky Mac queue"] = "Fronta u Lucky Mac",
  ["MAP"] = "MAPA",
  ["Make the menu rangeable. Fill the return type: iter.___[string]"] = "Udělej menu procházitelné přes range. Doplň návratový typ: iter.___[string]",
  ["Many readers at once, one writer. Fill the read lock: mu.___()"] = "Mnoho čtenářů naráz, jeden zapisovatel. Doplň zámek pro čtení: mu.___()",
  ["Map keys must support ==. Fill the constraint: func Has[K ___](m map[K]bool, k K)"] = "Klíče map musí podporovat ==. Doplň omezení: func Has[K ___](m map[K]bool, k K)",
  ["Maps"] = "Mapy",
  ["Marshal returns []byte and an error. Never ignore the error."] = "Marshal vrací []byte a error. Error nikdy neignoruj.",
  ["Mei"] = "Mei",
  ["Mei"] = "Mei",
  ["Mei"] = "Mei",
  ["Mei"] = "Mei",
  ["Memoization: check the map before computing. fib(90) becomes instant."] = "Memoizace: před výpočtem se podívej do mapy. fib(90) je rázem okamžité.",
  ["Merge sort recurses on both halves. Fill: merge(mergeSort(a[:m]), mergeSort(a[___]))"] = "Merge sort rekurzivně zpracuje obě půlky. Doplň: merge(mergeSort(a[:m]), mergeSort(a[___]))",
  ["Merge two sorted halves: take the smaller head and advance that side. Fill: ___++"] = "Slij dvě seřazené půlky: vezmi menší čelo a posuň tu stranu. Doplň: ___++",
  ["Modules and the go tool"] = "Moduly a nástroj go",
  ["Morning set. Don't show him your laptop bugs."] = "Ranní menu. Neukazuj mu bugy z notebooku.",
  ["Morning set. Lucky Mac. The kiosk on the door is stuck on a Go bug."] = "Ranní menu. Lucky Mac. Kiosek na dveřích se zasekl na bugu v Go.",
  ["Most tree questions are this shape: nil returns a base value, else combine both sides."] = "Většina otázek na stromy má tento tvar: nil vrátí základní hodnotu, jinak zkombinuj obě strany.",
  ["Muffin ready, or hash brown, or timeout. Pick one."] = "Muffin hotový, nebo hash brown, nebo timeout. Vyber jedno.",
  ["Must start with Test and take *testing.T. File name ends with _test.go."] = "Musí začínat Test a brát *testing.T. Název souboru končí _test.go.",
  ["Mutex and WaitGroup"] = "Mutex a WaitGroup",
  ["Mutex locks shared memory. WaitGroup waits for a set of goroutines to finish."] = "Mutex zamyká sdílenou paměť. WaitGroup čeká, až skupina goroutin skončí.",
  ["Mutual exclusion. Capital M. In package sync."] = "Vzájemné vyloučení. Velké M. V balíčku sync.",
  ["NEXT"] = "DÁL",
  ["NEXT >"] = "DÁL >",
  ["Named types, assertions, type switch"] = "Pojmenované typy, aserce, type switch",
  ["Newer Go has helpers for that. Lunch is on the house."] = "Novější Go na to má pomocníky. Oběd je na účet podniku.",
  ["Next of Next. The loop condition already checked fast.Next is not nil."] = "Next od Next. Podmínka smyčky už ověřila, že fast.Next není nil.",
  ["Nine letters. go test -bench=. runs them."] = "Devět písmen. go test -bench=. je spustí.",
  ["Not TODO (that is a placeholder). The empty, never-cancelled root."] = "Ne TODO (to je zástupka). Prázdný kořen, který se nikdy nezruší.",
  ["Not equal. The statement before ; runs first, and err lives only inside the if."] = "Nerovná se. Příkaz před ; běží první a err žije jen uvnitř if.",
  ["Not null, not None. Three letters. The only zero for interfaces with no type."] = "Ne null, ne None. Tři písmena. Jediná nula pro interface bez typu.",
  ["Not quite. Read the hint and try again. HINT again shows the answer."] = "Skoro. Přečti si tip a zkus to znovu. TIP podruhé ukáže odpověď.",
  ["Number in the brackets, then the element type. It cannot grow."] = "Číslo v hranatých závorkách, pak typ prvku. Nemůže růst.",
  ["Number the constants 0, 1, 2 automatically. Which identifier?"] = "Očísluj konstanty 0, 1, 2 automaticky. Který identifikátor?",
  ["OK"] = "OK",
  ["Octopus tap. The gate function returns ok, err."] = "Přilož Octopus. Funkce turniketu vrací ok, err.",
  ["One Unicode character in single quotes. Which type?"] = "Jeden znak Unicode v jednoduchých uvozovkách. Jaký typ?",
  ["One function for muffin or hash brown. Don't copy-paste."] = "Jedna funkce pro muffin i hash brown. Žádné copy-paste.",
  ["One less than n. fact(n) would never terminate."] = "O jedna méně než n. fact(n) by nikdy neskončilo.",
  ["One pass, one map: O(n). Store after checking so x does not pair with itself."] = "Jeden průchod, jedna mapa: O(n). Ulož až po kontrole, aby se x nespárovalo samo se sebou.",
  ["One pointer per node: singly linked. Two (Prev) makes it doubly linked."] = "Jeden ukazatel na uzel: jednosměrně zřetězený. Dva (Prev) dělají obousměrně zřetězený.",
  ["Only names that start with a capital letter leave their package. Which fmt function prints a line?"] = "Jen jména začínající velkým písmenem opouštějí svůj balíček. Která funkce z fmt vytiskne řádek?",
  ["Only the sender closes. Sending after this panics."] = "Zavírá jen odesílatel. Poslání po zavření způsobí panic.",
  ["Only the sender should call it. Never close from the receive side."] = "Volá ji jen odesílatel. Nikdy nezavírej ze strany příjemce.",
  ["Only useful inside defer. Returns nil if we are not panicking."] = "Užitečné jen uvnitř defer. Vrací nil, pokud nepanikaříme.",
  ["Opposite of var. Compile error if you try to change it."] = "Opak var. Chyba překladu, když ji zkusíš změnit.",
  ["Order 18. Morning set. Don't forget to cancel the context."] = "Objednávka 18. Ranní menu. Nezapomeň zrušit context.",
  ["Order is a struct. Point at it. The till talks through an interface."] = "Order je struct. Ukaž na něj. Pokladna mluví přes rozhraní.",
  ["Orders come through the web now. Put a handler on /order."] = "Objednávky teď chodí přes web. Dej handler na /order.",
  ["PERFECT!"] = "SKVĚLE!",
  ["PORT"] = "VÝŠKA",
  ["Packages and imports"] = "Balíčky a importy",
  ["Pay() can fail. Check the error. Close the drawer with defer."] = "Pay() může selhat. Zkontroluj chybu. Šuplík zavři pomocí defer.",
  ["Percival Street"] = "Percival Street",
  ["Percival Street at dawn. Walk if the crossing is clear, else wait. Go has no while: a for with a condition is the while."] = "Percival Street za svítání. Jdi, když je přechod volný, jinak čekej. Go nemá while: for s podmínkou je while.",
  ["Pick a branch by value without a chain of ifs. Which keyword?"] = "Vyber větev podle hodnoty bez řetězce ifů. Které klíčové slovo?",
  ["Point the current node backwards. Fill: cur.Next = ___"] = "Otoč aktuální uzel dozadu. Doplň: cur.Next = ___",
  ["Pointer receiver to mutate or for big structs; value receiver for small read-only types."] = "Ukazatelový receiver pro změny nebo velké structy; hodnotový receiver pro malé typy jen pro čtení.",
  ["Pointer to the same struct type, like the tree node."] = "Ukazatel na tentýž typ struct, jako u uzlu stromu.",
  ["Price list is a map. Hash brown: 8 dollars."] = "Ceník je mapa. Hash brown: 8 dolarů.",
  ["Print the struct with its field names. Which verb?"] = "Vypiš struct s názvy polí. Který verb?",
  ["Print the values sorted: left subtree, node, right subtree. Fill the first call."] = "Vypiš hodnoty seřazené: levý podstrom, uzel, pravý podstrom. Doplň první volání.",
  ["Print then ln. fmt.println with a small p does not exist outside fmt."] = "Print a pak ln. fmt.println s malým p mimo fmt neexistuje.",
  ["Problem five: search and sort. Binary search on a sorted slice with half-open bounds, then merge sort, the recursion every interviewer loves. And the one-liner from the library."] = "Úloha pět: hledání a řazení. Binární vyhledávání v seřazeném slice s polootevřenými mezemi, pak merge sort, rekurze, kterou miluje každý u pohovoru. A jednořádkovka z knihovny.",
  ["Problem four: the order queue as a singly linked list. Reverse it in place with three pointers, then detect a cycle with two runners of different speed."] = "Úloha čtyři: fronta objednávek jako jednosměrně zřetězený seznam. Otoč ji na místě třemi ukazateli, pak odhal cyklus dvěma běžci různé rychlosti.",
  ["Problem seven, the one they always ask: N workers pull jobs from a channel and push results. Get the close and the wait in the right order and the job is yours."] = "Úloha sedm, ta, na kterou se ptají vždycky: N workerů bere úlohy z channelu a posílá výsledky. Dej close a wait ve správném pořadí a místo je tvoje.",
  ["Problem six: the classics. Two numbers that add up to the set price, a palindrome check that handles CJK, and whether two dish names are anagrams."] = "Úloha šest: klasika. Dvě čísla se součtem rovným ceně menu, test palindromu, který zvládne CJK, a zda jsou dva názvy jídel anagramy.",
  ["Problem three: walk the MTR graph. Breadth-first with a queue for shortest hops, depth-first with recursion for reachability. Both need a visited set."] = "Úloha tři: projdi graf MTR. Do šířky s frontou pro nejmenší počet přestupů, do hloubky s rekurzí pro dosažitelnost. Obě potřebují množinu navštívených.",
  ["Problem two: a binary search tree of order numbers. Insert, walk in order, measure the height. In Go a tree is just a struct with two pointers and a nil at every leaf."] = "Úloha dvě: binární vyhledávací strom čísel objednávek. Vlož, projdi in-order, změř výšku. V Go je strom jen struct se dvěma ukazateli a nil v každém listu.",
  ["Pull a *RefundError out of the chain to read its fields. Fill: errors.___(err, &re)"] = "Vytáhni z řetězu *RefundError a přečti jeho pole. Doplň: errors.___(err, &re)",
  ["Q other quest"] = "Q jiná mise",
  ["Q: "] = "Q: ",
  ["QUEST %d"] = "MISE %d",
  ["R then Lock. Writers still use Lock and Unlock."] = "R, pak Lock. Zapisovatelé dál používají Lock a Unlock.",
  ["ROUND 1  -  the buzzer"] = "KOLO 1  -  bzučák",
  ["ROUND 2  -  the tree"] = "KOLO 2  -  strom",
  ["ROUND 3  -  the map"] = "KOLO 3  -  mapa",
  ["ROUND 4  -  the chain"] = "KOLO 4  -  řetěz",
  ["ROUND 5  -  the shuffle"] = "KOLO 5  -  míchání",
  ["ROUND 6  -  the classics"] = "KOLO 6  -  klasika",
  ["RWMutex: RLock for readers, Lock for the one writer. Use it when reads dominate."] = "RWMutex: RLock pro čtenáře, Lock pro jediného zapisovatele. Použij, když převažuje čtení.",
  ["Reached an empty spot: make the node here. Fill: if n == ___"] = "Došli jsme na prázdné místo: vytvoř uzel tady. Doplň: if n == ___",
  ["Read JSON bytes into the struct. Fill: json.___(b, &order)"] = "Načti JSON bajty do structu. Doplň: json.___(b, &order)",
  ["Receive until the channel is closed. Fill: for m := ___ ch"] = "Přijímej, dokud se kanál nezavře. Doplň: for m := ___ ch",
  ["Recurse into the same side you assign to. Mirror of the else branch."] = "Rekurze do stejné strany, do které přiřazuješ. Zrcadlo větve else.",
  ["Recursion and memoization"] = "Rekurze a memoizace",
  ["Recursive types need a pointer. nil children mark the end."] = "Rekurzivní typy potřebují ukazatel. Potomci nil značí konec.",
  ["Release the lock however the function exits. Fill: defer mu.___()"] = "Uvolni zámek, ať funkce skončí jakkoli. Doplň: defer mu.___()",
  ["Remove a key from a map. Which built-in?"] = "Odstraň klíč z mapy. Která vestavěná funkce?",
  ['Report a failed check and keep the test running. Fill: t.___("got %d", n)'] = 'Nahlas neúspěšnou kontrolu a nech test běžet dál. Doplň: t.___("got %d", n)',
  ["Response + Writer. An interface, so no star. It is also an io.Writer."] = "Response + Writer. Rozhraní, takže bez hvězdičky. Je to také io.Writer.",
  ["ResponseWriter: headers, status, body. Write the status before the body."] = "ResponseWriter: hlavičky, status, tělo. Status zapiš před tělem.",
  ["Return the cached answer if it is there. Fill the comma-ok test: if v, ok := memo[n]; ___"] = "Vrať uloženou odpověď, pokud existuje. Doplň test comma-ok: if v, ok := memo[n]; ___",
  ["Returns a channel that fires once, later. Capital A."] = "Vrací kanál, který jednou, později, vystřelí. Velké A.",
  ["Reverse with prev/cur/next pointers. Floyd's cycle check: slow moves one, fast moves two."] = "Otočení ukazateli prev/cur/next. Floydův test cyklu: slow jde o jeden, fast o dva.",
  ["Run close() when this function returns, even on error. Which keyword?"] = "Spusť close(), až tato funkce skončí, i při chybě. Které klíčové slovo?",
  ["Run cross(), then test its error in the same if. Fill the operator: err ___ nil"] = "Spusť cross() a pak otestuj jeho chybu ve stejném if. Doplň operátor: err ___ nil",
  ["Run the cooks, stop on the first error, wait for all. Fill: g.___()"] = "Spusť kuchaře, zastav při první chybě, počkej na všechny. Doplň: g.___()",
  ["Rune, Count, In, String: one long name. Or len([]rune(s))."] = "Rune, Count, In, String: jeden dlouhý název. Nebo len([]rune(s)).",
  ["S for string, then printf. Fprintf writes to a writer, Printf to stdout."] = "S jako string, pak printf. Fprintf píše do writeru, Printf na stdout.",
  ["STOP"] = "STOP",
  ["STREAK x%d"] = "SÉRIE x%d",
  ["Same built-in as for slices. A literal map[string]int{} also works."] = "Stejná vestavěná funkce jako pro slice. Literál map[string]int{} funguje také.",
  ["Same keyword as for slices. No index; just the value."] = "Stejné klíčové slovo jako u slice. Bez indexu; jen hodnota.",
  ["Same name as strings.Contains. Index returns the position or -1."] = "Stejný název jako strings.Contains. Index vrací pozici nebo -1.",
  ["Same word as WaitGroup's. It returns the first non-nil error."] = "Stejné slovo jako u WaitGroup. Vrací první error, který není nil.",
  ["Same word as a single import, then parentheses."] = "Stejné slovo jako u jednoho importu, pak závorky.",
  ["Same word as in switch. Turns select into a poll."] = "Stejné slovo jako ve switch. Ze select udělá neblokující dotaz.",
  ["Satisfied implicitly: any type with those methods implements it."] = "Splněno implicitně: každý typ s těmi metodami ho implementuje.",
  ["Save next, flip the link, advance both. prev is the new head when the loop ends."] = "Ulož next, otoč odkaz, posuň oba. Po skončení smyčky je prev nová hlava.",
  ["Schedules a call for later. Last in, first out. After the return happens."] = "Naplánuje volání na později. Poslední dovnitř, první ven. Až po return.",
  ["Send a value into the channel. Fill the operator: ch ___ muffin"] = "Pošli hodnotu do kanálu. Doplň operátor: ch ___ muffin",
  ["Send the jobs, then tell the workers there are no more. Which built-in?"] = "Pošli úlohy, pak řekni workerům, že další nebudou. Která vestavěná funkce?",
  ['Serve /order with the function serve. Fill: http.___("/order", serve)'] = 'Obsluhuj /order funkcí serve. Doplň: http.___("/order", serve)',
  ["Shipped. One more: the code still sorts by hand."] = "Nasazeno. Ještě jedno: kód pořád řadí ručně.",
  ["Short declaration. Fill the operator: floor ___ 8"] = "Krátká deklarace. Doplň operátor: floor ___ 8",
  ["Short for format. Println lives there."] = "Zkratka slova format. Println bydlí tam.",
  ["Short for function. Then the name, then arguments in parentheses."] = "Zkratka slova function. Pak jméno, pak argumenty v závorkách.",
  ["Shout the shop name. Which strings function upper-cases?"] = "Zakřič název obchodu. Která funkce ze strings dělá velká písmena?",
  ["Siu Ming"] = "Siu Ming",
  ["Siu Ming"] = "Siu Ming",
  ["Siu Ming"] = "Siu Ming",
  ["Siu Ming"] = "Siu Ming",
  ["Six letters, under sync/. Go 1.19 also has atomic.Int64 with .Add(1)."] = "Šest písmen, pod sync/. Go 1.19 má i atomic.Int64 s .Add(1).",
  ["Six letters. Every result, in order, comma separated."] = "Šest písmen. Každý výsledek, v pořadí, oddělený čárkou.",
  ["Skip a closed shop and go on to the next one. Which keyword?"] = "Přeskoč zavřený obchod a jdi na další. Které klíčové slovo?",
  ["Slices alias. Use copy() or append([]int(nil), a...) when you need your own."] = "Slice sdílejí paměť. Použij copy() nebo append([]int(nil), a...), když potřebuješ vlastní.",
  ["Smaller goes left, bigger goes right. Draw it before you type it."] = "Menší doleva, větší doprava. Nakresli si to, než to napíšeš.",
  ["Smaller values go left. Fill: n.Left = insert(n.___, v)"] = "Menší hodnoty jdou doleva. Doplň: n.Left = insert(n.___, v)",
  ["Sogo"] = "Sogo",
  ["Sogo's directory is a map from shop name to floor. Missing keys return the zero value, so you must ask comma-ok before you trust the number."] = "Adresář v Sogo je mapa z názvu obchodu na patro. Chybějící klíče vracejí nulovou hodnotu, takže se musíš zeptat comma-ok, než číslu uvěříš.",
  ["Sort the names in place. Fill: slices.___(names)"] = "Seřaď jména na místě. Doplň: slices.___(names)",
  ["Sorted prices. Find 25 in log n. Then sort the unsorted ones in n log n."] = "Seřazené ceny. Najdi 25 v log n. Pak seřaď ty neseřazené v n log n.",
  ["Sprintf returns the text. %s string, %d int, %v anything."] = "Sprintf vrací text. %s string, %d int, %v cokoli.",
  ["Star before the type. & takes the address. *p reads through it."] = "Hvězdička před typem. & vezme adresu. *p čte skrz něj.",
  ["Star then the type name. A value receiver (o Order) would change a copy."] = "Hvězdička a pak název typu. Hodnotový receiver (o Order) by změnil kopii.",
  ["Start a new module for the project. Fill the subcommand: go ___ init"] = "Založ pro projekt nový modul. Doplň podpříkaz: go ___ init",
  ["Start an anonymous function as a goroutine. What closes the line?"] = "Spusť anonymní funkci jako goroutine. Co uzavírá řádek?",
  ["Start fry() in a new goroutine. Which keyword?"] = "Spusť fry() v nové goroutine. Které klíčové slovo?",
  ['Start the server on port 8080 and block. Fill: http.___(":8080", nil)'] = 'Spusť server na portu 8080 a blokuj. Doplň: http.___(":8080", nil)',
  ["Start three workers, counting each one first. Fill: wg.___(1)"] = "Spusť tři workery, každého nejdřív započítej. Doplň: wg.___(1)",
  ["Steam. Hash brown. We did it."] = "Pára. Hash brown. Dokázali jsme to.",
  ["Stop everything: the till has no paper and that is a bug. Which built-in raises the crash?"] = "Zastav vše: v pokladně došel papír a to je bug. Která vestavěná funkce vyvolá pád?",
  ["Stop when the guest walks out. Fill: case <-ctx.___()"] = "Zastav, když host odejde. Doplň: case <-ctx.___()",
  ["Store into memo[n] before returning. Same shape works for any overlapping subproblem."] = "Před návratem ulož do memo[n]. Stejný vzor funguje pro každý překrývající se podproblém.",
  ["String() string satisfies fmt.Stringer. Println and %v call it automatically."] = "String() string splňuje fmt.Stringer. Println a %v ji volají automaticky.",
  ["Strings, runes, bytes"] = "Stringy, runy, bajty",
  ["Struct tags and encoding/json"] = "Struct tagy a encoding/json",
  ["Struct tags are strings after the type. json, xml, db... each package reads its own."] = "Struct tagy jsou stringy za typem. json, xml, db... každý balíček čte ten svůj.",
  ["Structs, pointers, methods, interfaces"] = "Structy, ukazatele, metody, rozhraní",
  ["TAB again: answer   ESC map"] = "TAB znovu: odpověď   ESC mapa",
  ["TAB hint   F5 auto   ESC map"] = "TAB tip   F5 auto   ESC mapa",
  ['Take the address of a new Order so p is a *Order. Fill: p := ___Order{Item: "set"}'] = 'Vezmi adresu nového Order, aby p bylo *Order. Doplň: p := ___Order{Item: "set"}',
  ["Take the front station off the queue. Fill: queue = queue[___]"] = "Vezmi přední stanici z fronty. Doplň: queue = queue[___]",
  ["Tell receivers no more hash browns will come. Which built-in?"] = "Řekni příjemcům, že další hash browny už nepřijdou. Která vestavěná funkce?",
  ["That is BFS: pop front, push unseen neighbours. First arrival is the shortest path."] = "To je BFS: vyjmi zepředu, přidej nenavštívené sousedy. První příchod je nejkratší cesta.",
  ["The MTR gate is a function: tap(card) (ok bool, err error). Go functions can return more than one value. That is how errors travel."] = "Turniket MTR je funkce: tap(card) (ok bool, err error). Funkce v Go mohou vracet víc než jednu hodnotu. Tak cestují chyby.",
  ["The MTR map is a graph. Level by level is BFS; as deep as you can is DFS."] = "Mapa MTR je graf. Úroveň po úrovni je BFS; co nejhlouběji je DFS.",
  ["The argument is evaluated on the defer line. Only the call is delayed."] = "Argument se vyhodnotí na řádku s defer. Odloží se jen volání.",
  ["The bell"] = "Zvonek",
  ["The blank identifier. Compile error if you name a value you never use."] = "Prázdný identifikátor. Chyba překladu, když pojmenuješ hodnotu, kterou nikdy nepoužiješ.",
  ["The board mixes prices, names and a sold-out flag. What is v today?"] = "Tabule míchá ceny, názvy a příznak vyprodáno. Co je v dnes?",
  ["The bool from the map lookup. True when the key exists."] = "Bool z vyhledání v mapě. True, když klíč existuje.",
  ["The booth"] = "Box",
  ["The booth code used to duplicate fry for every item. Generics write it once. A Kitchen that embeds Grill gets Grill's methods for free."] = "Kód u boxu dřív kopíroval fry pro každou položku. Generika ho napíšou jednou. Kitchen, který vnořuje Grill, dostane metody Grill zdarma.",
  ["The buffer size is the number of tokens. The fourth send waits."] = "Velikost bufferu je počet tokenů. Čtvrté odeslání čeká.",
  ["The built-in constraint for types that allow == and !=."] = "Vestavěné omezení pro typy, které umí == a !=.",
  ["The built-in interface for failure. Last return value by convention."] = "Vestavěné rozhraní pro selhání. Podle konvence poslední návratová hodnota.",
  ["The cheapest of three prices, no loop, no import. Which built-in (Go 1.21)?"] = "Nejlevnější ze tří cen, bez smyčky, bez importu. Která vestavěná funkce (Go 1.21)?",
  ["The comma-ok idiom. Same word twice on those two lines."] = "Idiom comma-ok. Stejné slovo dvakrát na těch dvou řádcích.",
  ["The cube is a slice of ads. append one more."] = "Kostka je slice reklam. append ještě jednu.",
  ["The current value. Its partner is target minus it."] = "Aktuální hodnota. Jejím partnerem je target minus ona.",
  ["The first handler argument is where the reply goes. Fill its type: w http.___"] = "První argument handleru je místo, kam jde odpověď. Doplň jeho typ: w http.___",
  ["The first line of go.mod names the module. Which keyword?"] = "První řádek go.mod pojmenuje modul. Které klíčové slovo?",
  ["The flat"] = "Byt",
  ["The full word this time. Then the go version, then require lines."] = "Tentokrát celé slovo. Pak verze go, pak řádky require.",
  ["The function calls itself. Same name as on the last line."] = "Funkce volá sama sebe. Stejné jméno jako na posledním řádku.",
  ["The function itself. The map is shared, so a plain map argument works."] = "Funkce sama. Mapa je sdílená, takže stačí obyčejný argument typu map.",
  ["The index of the left half, mirroring j++ in the else."] = "Index levé půlky, zrcadlo j++ ve větvi else.",
  ["The int32 code point type. Indexing a string gives bytes."] = "Typ kódového bodu int32. Indexování stringu dává bajty.",
  ["The key exactly as the phone spells it, inside the quotes."] = "Klíč přesně tak, jak ho píše telefon, uvnitř uvozovek.",
  ["The keyword type, where a type name would go. Only inside a switch."] = "Klíčové slovo type tam, kde by byl název typu. Jen uvnitř switch.",
  ["The kitchen"] = "Kuchyně",
  ["The kitchen is concurrent. One cook cannot wait for the hash brown before starting the muffin. go fry() starts a function in a new goroutine."] = "Kuchyně je souběžná. Kuchař nemůže čekat na hash brown, než začne muffin. go fry() spustí funkci v nové goroutine.",
  ["The lift"] = "Výtah",
  ["The lift panel is a tiny Go program. Floor, name, and a constant for Lucky Mac's opening hour. Zero values matter: an unset int is not blank."] = "Panel výtahu je malý program v Go. Patro, jméno a konstanta pro otevírací hodinu Lucky Mac. Na nulových hodnotách záleží: nenastavený int není prázdný.",
  ["The menu board"] = "Tabule s menu",
  ["The middle index without overflow. Fill: mid := lo + (hi-lo)/___"] = "Prostřední index bez přetečení. Doplň: mid := lo + (hi-lo)/___",
  ["The morning set"] = "Ranní menu",
  ["The multiplicative identity. Returning 0 would zero every factorial."] = "Neutrální prvek násobení. Vrácení 0 by vynulovalo každý faktoriál.",
  ["The new sign says 銅鑼灣. The app counts it as nine letters."] = "Na nové ceduli je 銅鑼灣. Appka to počítá jako devět písmen.",
  ["The node we just came from. nil on the first step, which becomes the new tail."] = "Uzel, ze kterého jsme přišli. V prvním kroku nil, z něj bude nový konec.",
  ["The opposite of Lock. defer it on the very next line."] = "Opak Lock. Dej ho do defer hned na dalším řádku.",
  ["The opposite of the -- below. Go's ++ is a statement, not an expression."] = "Opak -- níže. ++ je v Go příkaz, ne výraz.",
  ["The order app"] = "Objednávková appka",
  ["The other child. max is a Go 1.21 built-in."] = "Druhý potomek. max je vestavěná funkce od Go 1.21.",
  ["The package the Go tool looks for when you type go run."] = "Balíček, který nástroj go hledá, když napíšeš go run.",
  ["The pass"] = "Výdej",
  ["The pass window is a channel. One goroutine fries, another plates. Do not share the same variable; send the value through the pipe."] = "Výdejní okénko je kanál. Jedna goroutine smaží, druhá servíruje. Nesdílej stejnou proměnnou; pošli hodnotu rourou.",
  ["The phone calls the field dish, not Item. Fill the tag so json reads that key."] = "Telefon říká poli dish, ne Item. Doplň tag, aby json četl ten klíč.",
  ['The phone sends the price as text. Parse "18" into an int. Which strconv function?'] = 'Telefon posílá cenu jako text. Převeď "18" na int. Která funkce ze strconv?',
  ['The phone sends {"dish":"set"}. Our struct says Item. Nothing arrives.'] = 'Telefon posílá {"dish":"set"}. Náš struct říká Item. Nic nedorazí.',
  ["The pickup bell is a select. Whichever channel is ready first wins. If none are ready, default fires instead of blocking the till."] = "Zvonek u výdeje je select. Vyhraje kanál, který je připraven první. Když žádný, spustí se default místo blokování pokladny.",
  ["The pointer that walks the list. prev is the new head once it is nil."] = "Ukazatel, který prochází seznam. Jakmile je nil, prev je nová hlava.",
  ["The queue is a linked list. Reverse it without allocating, then find the loop."] = "Fronta je zřetězený seznam. Otoč ji bez alokace, pak najdi smyčku.",
  ["The queue is a struct of orders. A method with a pointer receiver can change the order. The till only knows the Pay() interface, not the card type."] = "Fronta je struct objednávek. Metoda s ukazatelovým receiverem může objednávku změnit. Pokladna zná jen rozhraní Pay(), ne typ karty.",
  ["The recursive call must shrink the problem. Fill: return n * fact(___)"] = "Rekurzivní volání musí problém zmenšit. Doplň: return n * fact(___)",
  ["The refund desk"] = "Refundační pult",
  ["The rooftop"] = "Střecha",
  ["The root of every request tree. Fill: ctx := context.___()"] = "Kořen každého stromu requestů. Doplň: ctx := context.___()",
  ["The same keyword as for slices, now on an int. No i := 0; i < 3; i++."] = "Stejné klíčové slovo jako u slice, teď na int. Žádné i := 0; i < 3; i++.",
  ["The same word as a C-style counted loop."] = "Stejné slovo jako počítaný cyklus ve stylu C.",
  ["The same word as the blank import above. Go 1.16."] = "Stejné slovo jako v prázdném importu nahoře. Go 1.16.",
  ["The second argument holds the URL, method and body. Fill its type: r *http.___"] = "Druhý argument drží URL, metodu a tělo. Doplň jeho typ: r *http.___",
  ["The second argument to make is the buffer size."] = "Druhý argument make je velikost bufferu.",
  ["The signboard"] = "Cedule",
  ["The slice built-in that grows. Mark visited when you enqueue, not when you pop."] = "Vestavěná funkce, která slice rozšíří. Označ navštívené při zařazení, ne při vyjmutí.",
  ["The till"] = "Pokladna",
  ["The till returns (receipt, err). If err is not the zero value of error, stop. defer close() runs even if you return early."] = "Pokladna vrací (receipt, err). Pokud err není nulová hodnota error, zastav. defer close() běží, i když vrátíš dřív.",
  ["The tray is on the table. One last lesson: a request has a context so the kitchen can stop if the guest walks out. And a test so the next morning still compiles."] = "Tác je na stole. Poslední lekce: request má context, aby kuchyně mohla skončit, když host odejde. A test, aby se další ráno pořád kompilovalo.",
  ["The tray rail"] = "Lišta s tácy",
  ["The tuple assignment does all three moves at once: Go evaluates the right side first."] = "Vícenásobné přiřazení udělá všechny tři tahy najednou: Go nejdřív vyhodnotí pravou stranu.",
  ["The type name works as the conversion. Floor and int never mix silently."] = "Název typu funguje jako konverze. Floor a int se nikdy tiše nemíchají.",
  ["The type name, inside the parentheses. The second line shows the safe two-value form."] = "Název typu v závorkách. Druhý řádek ukazuje bezpečnou dvouhodnotovou formu.",
  ["The typed-nil trap: return a plain nil error, never a nil *MyError."] = "Past typovaného nil: vracej čistý nil error, nikdy nil *MyError.",
  ["The walk stops when the runner falls off the end. Fill the condition: ___ != nil"] = "Průchod končí, když běžec spadne z konce. Doplň podmínku: ___ != nil",
  ["The web counter"] = "Webový pult",
  ["The workshop"] = "Dílna",
  ["The zero pointer. This is the base case of the tree recursion."] = "Nulový ukazatel. To je základní případ rekurze nad stromem.",
  ["The zero value of a pointer, slice, map, chan, func, or error is ___."] = "Nulová hodnota pointeru, slice, mapy, chan, func nebo error je ___.",
  ["Three cooks, one ticket rail, one pass. That is a worker pool."] = "Tři kuchaři, jedna lišta s lístky, jedno výdejní okno. To je worker pool.",
  ["Three dots then the element type. Inside the function fares is a []int."] = "Tři tečky a pak typ prvku. Uvnitř funkce je fares []int.",
  ["Three letters, capital N. Takes the message, returns an error."] = "Tři písmena, velké N. Bere zprávu, vrací error.",
  ["Three letters, short for module. The same word as in go.mod."] = "Tři písmena, zkratka pro module. Stejné slovo jako v go.mod.",
  ["Three letters, short for sequence. Seq2 yields pairs, like index and value."] = "Tři písmena, zkratka pro sequence. Seq2 dává dvojice, třeba index a hodnotu.",
  ["Three letters. Capacity, not length."] = "Tři písmena. Kapacita, ne délka.",
  ["Three letters. Works anywhere; := only works inside a function."] = "Tři písmena. Funguje všude; := funguje jen uvnitř funkce.",
  ["Three letters. max is its twin. Both take any number of ordered values."] = "Tři písmena. max je její dvojče. Obě berou libovolný počet uspořádaných hodnot.",
  ["Three letters: to examine. ./... means this package and everything under it."] = "Tři písmena: prověřit. ./... znamená tento balíček a vše pod ním.",
  ["Throw away the bool, keep the error. What character discards?"] = "Zahoď bool, nech si error. Který znak zahazuje?",
  ["Ticket five: the app needs a server. net/http is in the standard library: a handler is a function, a route is a string, the server is one call."] = "Ticket pět: appka potřebuje server. net/http je ve standardní knihovně: handler je funkce, routa je string, server je jedno volání.",
  ["Ticket four: orders arrive as JSON. The decoder only sees exported fields, and a tag on the field tells it which key to read."] = "Ticket čtyři: objednávky chodí jako JSON. Dekodér vidí jen exportovaná pole a tag na poli mu říká, který klíč číst.",
  ["Ticket seven, the rooftop. The app is live. Newer Go has generic helpers so the old hand-written loops can go: slices, maps, min, and iterators you can range over."] = "Ticket sedm, střecha. Appka je živá. Novější Go má generické pomocníky, takže staré ručně psané smyčky můžou pryč: slices, maps, min a iterátory, přes které jde range.",
  ["Ticket six: ship it. A module names the project, go.mod pins the dependencies, and the go tool formats, checks and builds. No Makefile needed."] = "Ticket šest: nasaď to. Modul pojmenuje projekt, go.mod zafixuje závislosti a nástroj go formátuje, kontroluje a sestavuje. Žádný Makefile netřeba.",
  ["Ticket three: the menu board takes any. Before the app can print a price it must ask what is inside. Go asks with an assertion or a type switch."] = "Ticket tři: tabule s menu bere any. Než appka vypíše cenu, musí se zeptat, co je uvnitř. Go se ptá asercí nebo type switchem.",
  ["Ticket two: refunds. An error must say what went wrong, keep its cause, and let the caller ask which kind it was. All of that is in package errors."] = "Ticket dva: refundace. Error musí říct, co se pokazilo, uchovat příčinu a nechat volajícího zeptat se, jaký druh to byl. To všechno je v balíčku errors.",
  ["Tilde. Without it, type Cents int would not satisfy Number."] = "Tilda. Bez ní by type Cents int nesplňoval Number.",
  ["Time the grill. Fill the prefix: func ___Grill(b *testing.B)"] = "Změř gril. Doplň předponu: func ___Grill(b *testing.B)",
  ["Times Square"] = "Times Square",
  ["Times Square's LED cube is a slice of frames. An array has a fixed size in the type. A slice does not. append returns a (maybe new) slice."] = "LED kostka na Times Square je slice snímků. Pole má pevnou velikost v typu. Slice ne. append vrací (možná nový) slice.",
  ["To then Upper. Strings are immutable, so it returns a new one."] = "To a pak Upper. Stringy jsou neměnné, takže vrací nový.",
  ["Tram or walk? if the light is green, we go."] = "Tramvají, nebo pěšky? if je zelená, jdeme.",
  ["Turn the Order into JSON bytes. Fill: json.___(order)"] = "Převeď Order na JSON bajty. Doplň: json.___(order)",
  ["Two cooks increment the same tray count. Without a lock that is a race. WaitGroup.Add, Done, Wait is how the pass knows both items are ready."] = "Dva kuchaři zvyšují stejný počet táců. Bez zámku je to race. Přes WaitGroup.Add, Done, Wait výdej ví, že jsou obě položky hotové.",
  ["Two hands, one tray counter. Lock it. Then wait for both cooks."] = "Dvě ruce, jeden čítač táců. Zamkni ho. Pak počkej na oba kuchaře.",
  ["Two letters. == only checks the outer error; this unwraps."] = "Dvě písmena. == kontroluje jen vnější error; tohle rozbaluje.",
  ["Two letters. Is matches a value; this matches a type and fills the pointer."] = "Dvě písmena. Is hledá hodnotu; tohle hledá typ a naplní ukazatel.",
  ["Two letters. Then a function call. The caller does not wait."] = "Dvě písmena. Pak volání funkce. Volající nečeká.",
  ["Two packages in one file. What keyword opens the grouped list?"] = "Dva balíčky v jednom souboru. Které klíčové slovo otevírá seskupený seznam?",
  ["Two pointers walk inward from both ends. Fill the step: i, j = i+1, ___"] = "Dva ukazatele jdou z obou konců dovnitř. Doplň krok: i, j = i+1, ___",
  ["Two pointers: O(n) time, O(1) extra space. Same trick for sorted-array pair sums."] = "Dva ukazatele: čas O(n), O(1) paměti navíc. Stejný trik pro součty dvojic v seřazeném poli.",
  ["Two-sum, palindrome, anagram"] = "Two-sum, palindrom, anagram",
  ["Type parameters go in [T any]. Embedding promotes methods. A closure captures nearby names."] = "Typové parametry jdou do [T any]. Embedding povyšuje metody. Closure zachytí okolní jména.",
  ["Type the answer, then ENTER."] = "Napiš odpověď a stiskni ENTER.",
  ["Un + Marshal. It needs a pointer so it can fill your variable."] = "Un + Marshal. Potřebuje ukazatel, aby mohl naplnit tvou proměnnou.",
  ["Unexported fields are skipped silently. Capital letters or nothing."] = "Neexportovaná pole se tiše přeskočí. Velká písmena, nebo nic.",
  ["Unmarshal(data, &v). Without & it decodes into a copy and you see nothing."] = "Unmarshal(data, &v). Bez & dekóduje do kopie a ty nevidíš nic.",
  ["Unseen neighbours go to the back of the queue. Fill: queue = ___(queue, nb)"] = "Nenavštívení sousedé jdou na konec fronty. Doplň: queue = ___(queue, nb)",
  ["Variables, types, const"] = "Proměnné, typy, const",
  ["WHAT ALEX LEARNED: Go basics.   PRIZE: the morning set."] = "CO SE ALEX NAUČIL: základy Go.   ODMĚNA: ranní menu.",
  ["WHAT ALEX LEARNED: goroutines, channels, sync.   PRIZE: the morning set."] = "CO SE ALEX NAUČIL: goroutiny, kanály, sync.   ODMĚNA: ranní menu.",
  ["WHAT ALEX LEARNED: recursion, trees, graphs, lists, sorting, hashing, workers.   PRIZE: HIRED."] = "CO SE ALEX NAUČIL: rekurze, stromy, grafy, seznamy, řazení, hashování, workery.   ODMĚNA: PŘIJAT.",
  ["WHAT ALEX LEARNED: strings, errors, JSON, HTTP.   PRIZE: the app is live."] = "CO SE ALEX NAUČIL: stringy, chyby, JSON, HTTP.   ODMĚNA: aplikace běží.",
  ["WIND"] = "OKNO",
  ["Wait on muffin or hash brown, whichever is ready. Which keyword?"] = "Čekej na muffin nebo hash brown, co je dřív hotové. Které klíčové slovo?",
  ["Wait then close(results) in a goroutine: the receiver's range ends cleanly. No leaks."] = "Wait a pak close(results) v goroutině: range příjemce čistě skončí. Žádné úniky.",
  ["Wait until both cooks call Done. Fill: var wg sync.___"] = "Čekej, až oba kuchaři zavolají Done. Doplň: var wg sync.___",
  ["WaitGroup.Add(n), Done(), Wait(). The tray leaves when n hits zero."] = "WaitGroup.Add(n), Done(), Wait(). Tác odjíždí, když n klesne na nulu.",
  ["Walk every shop name in a slice. Fill: for _, name := ___ shops"] = "Projdi každé jméno obchodu ve slice. Doplň: for _, name := ___ shops",
  ["Warm the grill exactly once, however many cooks call it. Fill: var once sync.___"] = "Rozehřej gril přesně jednou, ať ho volá kolik chce kuchařů. Doplň: var once sync.___",
  ["Was the key there? The second result is a bool named ___."] = "Byl tam klíč? Druhý výsledek je bool jménem ___.",
  ["We already checked mid, so skip past it. hi = mid keeps the half-open rule."] = "mid jsme už zkontrolovali, tak ho přeskoč. hi = mid drží polootevřené pravidlo.",
  ["Welcome to CODE RUSH! Round one: factorial, then fib without the exponential blowup. Buzzer's live!"] = "Vítej v CODE RUSH! Kolo jedna: faktoriál, pak fib bez exponenciální exploze. Bzučák je živý!",
  ["What is the lightweight thread go starts called?"] = "Jak se jmenuje lehké vlákno, které go spouští?",
  ["Which standard package prints to the terminal?"] = "Který standardní balíček tiskne do terminálu?",
  ["With, then the word for a time limit. WithDeadline takes a clock time instead."] = "With, pak slovo pro časový limit. WithDeadline místo toho bere čas na hodinách.",
  ["WithTimeout returns a child that cancels itself. Always defer cancel() or you leak."] = "WithTimeout vrací potomka, který se sám zruší. Vždy defer cancel(), jinak vznikne únik.",
  ["Worker pool and pipeline"] = "Worker pool a pipeline",
  ["Worker pool: N goroutines range over a jobs channel; close(jobs) ends them; WaitGroup then close(results)."] = "Worker pool: N goroutin dělá range přes channel jobs; close(jobs) je ukončí; WaitGroup a pak close(results).",
  ["Workers are identical goroutines sharing one input channel. The channel is the queue."] = "Workery jsou totožné goroutiny sdílející jeden vstupní channel. Ten channel je fronta.",
  ["Works on slices, strings, maps, channels. cap is the capacity."] = "Funguje na slice, stringech, mapách, kanálech. cap je kapacita.",
  ["Write the reply into w, not the terminal. Which fmt function?"] = "Zapiš odpověď do w, ne do terminálu. Která funkce z fmt?",
  ["[3]string is an array: a value, fixed length, copied on assignment. []string is a slice."] = "[3]string je pole: hodnota, pevná délka, kopíruje se při přiřazení. []string je slice.",
  ["[T any] is the widest constraint. comparable is for map keys."] = "[T any] je nejširší omezení. comparable je pro klíče map.",
  ["[]int is a slice. [3]int is an array of three. Slices are what you use."] = "[]int je slice. [3]int je pole tří prvků. Používej slice.",
  ["[]rune(s) once, then index freely. Interviewers check this in Go."] = "[]rune(s) jednou, pak indexuj volně. U pohovoru na Go to zkoušejí.",
  ["_ means I know this exists and I am ignoring it on purpose."] = "_ znamená: vím, že to existuje, a schválně to ignoruji.",
  ['___ fry("hashbrown")\n___ toast("muffin")\n'] = '___ fry("hashbrown")\n___ toast("muffin")\n',
  ["___ luckymac/delivery\n\ngo 1.22\n\nrequire github.com/lib/pq v1.10.9\n"] = "___ luckymac/delivery\n\ngo 1.22\n\nrequire github.com/lib/pq v1.10.9\n",
  ["___ tap(card string) bool {\n    return true\n}\n"] = "___ tap(card string) bool {\n    return true\n}\n",
  ["___ {\ncase m := <-muffin:\n    serve(m)\ncase h := <-hash:\n    serve(h)\n}\n"] = "___ {\ncase m := <-muffin:\n    serve(m)\ncase h := <-hash:\n    serve(h)\n}\n",
  ["___(ch)\nx, ok := <-ch          // ok is false after\n"] = "___(ch)\nx, ok := <-ch          // ok je pak false\n",
  ["___(floors)                  // len(floors) == 0 after\n"] = "___(floors)                  // potom len(floors) == 0\n",
  ['___(prices, "closed")\n'] = '___(prices, "closed")\n',
  ['___, err := tap("octopus")\n'] = '___, err := tap("octopus")\n',
  ["a := []int{1, 2, 3}\nb := a[:2]\nb[0] = 9\nfmt.Println(a[0])       // prints ___\n"] = "a := []int{1, 2, 3}\nb := a[:2]\nb[0] = 9\nfmt.Println(a[0])       // vytiskne ___\n",
  ["a[mid] is too small: the answer is to the right. Fill: lo = ___ + 1"] = "a[mid] je moc malé: odpověď je vpravo. Doplň: lo = ___ + 1",
  ["arrows walk   ESC map"] = "šipky chůze   ESC mapa",
  ["b shares a's array. After b[0] = 9, what does a[0] print?"] = "b sdílí pole a. Co vytiskne a[0] po b[0] = 9?",
  ['b, err := json.___(order)   // []byte\nfmt.Println(string(b))      // {"dish":"set"}\n'] = 'b, err := json.___(order)   // []byte\nfmt.Println(string(b))      // {"dish":"set"}\n',
  ["break leaves the innermost for, switch or select. A label breaks an outer one."] = "break opustí nejvnitřnější for, switch nebo select. Návěští přeruší vnější.",
  ["cap is the room in the backing array. append doubles it when len reaches cap."] = "cap je místo v podkladovém poli. append ho zdvojnásobí, když len dosáhne cap.",
  ["ch := make(___)        // unbuffered\n"] = "ch := make(___)        // bez bufferu\n",
  ["ch := make(chan int)\nch <- 1                // nobody receives\nfmt.Println(<-ch)\n// fatal error: all goroutines are asleep - ___!\n"] = "ch := make(chan int)\nch <- 1                // nikdo nepřijímá\nfmt.Println(<-ch)\n// fatal error: all goroutines are asleep - ___!\n",
  ['ch := make(chan string)\nch ___ "muffin"        // send\n'] = 'ch := make(chan string)\nch ___ "muffin"        // odeslání\n',
  ['ch := make(chan string, ___)   // buffered\nch <- "muffin"                 // does not block yet\n'] = 'ch := make(chan string, ___)   // s bufferem\nch <- "muffin"                 // zatím neblokuje\n',
  ["ch <- x sends. x := <-ch receives. Same operator, different place."] = "ch <- x odesílá. x := <-ch přijímá. Stejný operátor, jiné místo.",
  ["chan is a typed pipe. <- sends and receives. close tells receivers to stop."] = "chan je typovaná roura. <- odesílá a přijímá. close řekne příjemcům, ať skončí.",
  ["chan struct{} plus close is the cheapest done signal. context.Done() returns one."] = "chan struct{} plus close je nejlevnější signál hotovo. context.Done() takový vrací.",
  ["cheapest := ___(muffin, hash, coffee)   // built-in\n"] = "cheapest := ___(muffin, hash, coffee)   // vestavěná\n",
  ["clear(m) deletes every key. Before 1.21 you looped with delete."] = "clear(m) smaže každý klíč. Před 1.21 ses točil v cyklu s delete.",
  ["close(ch). range ch stops when the channel is closed."] = "close(ch). range ch skončí, když je kanál zavřený.",
  ["close(jobs) is the shutdown signal: every worker's range loop drains and exits."] = "close(jobs) je signál k ukončení: smyčka range každého workera se vyprázdní a skončí.",
  ["comparable for map keys and ==. any allows everything but promises nothing."] = "comparable pro klíče map a ==. any povolí vše, ale nic neslibuje.",
  ["const (\n    Muffin = ___       // 0\n    Hash               // 1\n    Coffee             // 2\n)\n"] = "const (\n    Muffin = ___       // 0\n    Hash               // 1\n    Coffee             // 2\n)\n",
  ["const opens = 6. The lift knows when breakfast starts."] = "const opens = 6. Výtah ví, kdy začíná snídaně.",
  ["context carries deadlines and cancel. go test runs Test* in _test.go."] = "context nese deadliny a zrušení. go test spouští Test* v _test.go.",
  ["context.Background() then WithCancel. Always defer cancel()."] = "context.Background(), pak WithCancel. Vždy defer cancel().",
  ["continue skips one round; break ends the loop."] = "continue přeskočí jedno kolo; break cyklus ukončí.",
  ["ctx := context.___()\nctx, cancel := context.WithCancel(ctx)\ndefer cancel()\n"] = "ctx := context.___()\nctx, cancel := context.WithCancel(ctx)\ndefer cancel()\n",
  ["ctx, cancel := context.___(ctx, 2*time.Second)\ndefer cancel()          // always\n"] = "ctx, cancel := context.___(ctx, 2*time.Second)\ndefer cancel()          // vždy\n",
  ["ctx.Done() closes on cancel or deadline; ctx.Err() says which one."] = "ctx.Done() se zavře při zrušení nebo deadline; ctx.Err() řekne, které z nich.",
  ["default: runs when every channel would block. The till stays free."] = "default: běží, když by každý kanál blokoval. Pokladna zůstává volná.",
  ["defer captures its arguments now, not later. What does this print?"] = "defer zachytí argumenty hned, ne později. Co tohle vypíše?",
  ["defer evaluates arguments immediately. defer func() { fmt.Println(x) }() would print 2."] = "defer vyhodnotí argumenty ihned. defer func() { fmt.Println(x) }() by vypsalo 2.",
  ["defer f.Close(). The drawer shuts even if Pay fails."] = "defer f.Close(). Šuplík se zavře, i když Pay selže.",
  ["defer func() {\n    if r := ___(); r != nil {\n        // saved the till\n    }\n}()\n"] = "defer func() {\n    if r := ___(); r != nil {\n        // pokladna zachráněna\n    }\n}()\n",
  ["delete(m, k) removes it. Maps grow by assignment, shrink by this."] = "delete(m, k) ho odstraní. Mapy rostou přiřazením, zmenšují se tímhle.",
  ["delete(m, key). Safe if the key is already gone."] = "delete(m, key). Bezpečné, i když klíč už chybí.",
  ["done := make(chan ___)   // zero bytes per value\ngo func() {\n    cook()\n    close(done)\n}()\n<-done\n"] = "done := make(chan ___)   // nula bajtů na hodnotu\ngo func() {\n    cook()\n    close(done)\n}()\n<-done\n",
  ["error is an interface. Check err != nil. defer runs when the function returns."] = "error je interface. Kontroluj err != nil. defer běží, když funkce vrací.",
  ["error is interface{ Error() string }. Your own types can carry data."] = "error je interface{ Error() string }. Vlastní typy mohou nést data.",
  ["errors.As finds the first error of that type and stores it in re."] = "errors.As najde první error toho typu a uloží ho do re.",
  ["errors.Is compares values down the chain. Use it instead of ==."] = "errors.Is porovnává hodnoty podél řetězu. Používej ho místo ==.",
  ["errors.New for fixed messages; name them ErrSomething at package level."] = "errors.New pro pevné zprávy; na úrovni balíčku je pojmenuj ErrSomething.",
  ["errors.New makes one. %w wraps one. errors.Is and errors.As search the chain."] = "errors.New ho vytvoří. %w ho obalí. errors.Is a errors.As prohledají řetěz.",
  ['f, err := os.Open("order.txt")\n___ f.Close()\n'] = 'f, err := os.Open("order.txt")\n___ f.Close()\n',
  ["fmt prints a type your way if it has one method. Fill: func (o Order) ___() string"] = "fmt vytiskne typ po tvém, když má jednu metodu. Doplň: func (o Order) ___() string",
  ['fmt.___(w, "served %s", item)   // w is an io.Writer\n'] = 'fmt.___(w, "served %s", item)   // w je io.Writer\n',
  ["for _, s := range shops {\n    if s.closed {\n        ___                // next shop\n    }\n    fmt.Println(s.name)\n}\n"] = "for _, s := range shops {\n    if s.closed {\n        ___                // další obchod\n    }\n    fmt.Println(s.name)\n}\n",
  ['for _, s := range shops {\n    if s.name == "Lucky Mac" {\n        found = s\n        ___\n    }\n}\n'] = 'for _, s := range shops {\n    if s.name == "Lucky Mac" {\n        found = s\n        ___\n    }\n}\n',
  ["for i := ___ 3 {        // 0, 1, 2\n    fmt.Println(i)\n}\n"] = "for i := ___ 3 {        // 0, 1, 2\n    fmt.Println(i)\n}\n",
  ["for i < 8 is a while. for { } is forever. for i := 0; i < n; i++ counts."] = "for i < 8 je while. for { } je navždy. for i := 0; i < n; i++ počítá.",
  ["for i, j := 0, 0; i < len(l) && j < len(r); {\n    if l[i] <= r[j] {\n        out = append(out, l[i])\n        ___++\n    } else {\n        out = append(out, r[j])\n        j++\n"] = "for i, j := 0, 0; i < len(l) && j < len(r); {\n    if l[i] <= r[j] {\n        out = append(out, l[i])\n        ___++\n    } else {\n        out = append(out, r[j])\n        j++\n",
  ['for i, r := range "銅鑼灣" {\n    fmt.Println(i, ___(r))   // 0 銅, 3 鑼, 6 灣\n}\n'] = 'for i, r := range "銅鑼灣" {\n    fmt.Println(i, ___(r))   // 0 銅, 3 鑼, 6 灣\n}\n',
  ["for i, v := range s. Use _ when you do not need the index."] = "for i, v := range s. Použij _, když index nepotřebuješ.",
  ["for j := 1; j <= 9; j++ {\n    jobs <- j\n}\n___(jobs)                    // workers' range loops end\n"] = "for j := 1; j <= 9; j++ {\n    jobs <- j\n}\n___(jobs)                    // smyčky range workerů skončí\n",
  ["for len(queue) > 0 {\n    st := queue[0]\n    queue = queue[___]      // dequeue\n    fmt.Println(st)\n"] = "for len(queue) > 0 {\n    st := queue[0]\n    queue = queue[___]      // vyjmi z fronty\n    fmt.Println(st)\n",
  ["for m := ___ ch {       // ends when ch is closed\n    serve(m)\n}\n"] = "for m := ___ ch {       // končí, když je ch zavřený\n    serve(m)\n}\n",
  ['func (o Order) ___() string {\n    return o.Item + " $" + strconv.Itoa(o.Price)\n}\nfmt.Println(o)          // set $25\n'] = 'func (o Order) ___() string {\n    return o.Item + " $" + strconv.Itoa(o.Price)\n}\nfmt.Println(o)          // set $25\n',
  ["func (o ___) Add(p int) {   // pointer receiver\n    o.Price += p            // changes the caller's Order\n}\n"] = "func (o ___) Add(p int) {   // ukazatelový receiver\n    o.Price += p            // mění Order volajícího\n}\n",
  ["func Has[K ___](m map[K]bool, k K) bool {\n    _, ok := m[k]\n    return ok\n}\n"] = "func Has[K ___](m map[K]bool, k K) bool {\n    _, ok := m[k]\n    return ok\n}\n",
  ["func Items() iter.___[string] {     // Go 1.23\n    return func(yield func(string) bool) {\n        for _, it := range menu {\n            if !yield(it) { return }\n        }\n    }\n}\n"] = "func Items() iter.___[string] {     // Go 1.23\n    return func(yield func(string) bool) {\n        for _, it := range menu {\n            if !yield(it) { return }\n        }\n    }\n}\n",
  ["func TestOrder(t *testing.T). go test ./...  The morning set is served."] = "func TestOrder(t *testing.T). go test ./...  Ranní menu je na stole.",
  ['func TestPrice(t *testing.T) {\n    if n := price("set"); n != 25 {\n        t.___("got %d, want 25", n)\n    }\n}\n'] = 'func TestPrice(t *testing.T) {\n    if n := price("set"); n != 25 {\n        t.___("got %d, want 25", n)\n    }\n}\n',
  ['func ___(t *testing.T) {\n    t.Run("set", func(t *testing.T) {})\n}\n'] = 'func ___(t *testing.T) {\n    t.Run("set", func(t *testing.T) {})\n}\n',
  ["func ___Grill(b *testing.B) {\n    for i := 0; i < b.N; i++ {\n        grill()\n    }\n}\n"] = "func ___Grill(b *testing.B) {\n    for i := 0; i < b.N; i++ {\n        grill()\n    }\n}\n",
  ["func add(n int) func(int) int {\n    return func(x int) int {\n        return x + n     // a ___\n    }\n}\n"] = "func add(n int) func(int) int {\n    return func(x int) int {\n        return x + n     // tohle je ___\n    }\n}\n",
  ["func dfs(st string, seen map[string]bool) {\n    seen[st] = true\n    for _, nb := range lines[st] {\n        if !seen[nb] { ___(nb, seen) }\n    }\n}\n"] = "func dfs(st string, seen map[string]bool) {\n    seen[st] = true\n    for _, nb := range lines[st] {\n        if !seen[nb] { ___(nb, seen) }\n    }\n}\n",
  ["func fact(n int) int {\n    if n <= 1 {\n        return 1\n    }\n    return n * fact(___)    // toward the base case\n}\n"] = "func fact(n int) int {\n    if n <= 1 {\n        return 1\n    }\n    return n * fact(___)    // směrem k základnímu případu\n}\n",
  ["func fact(n int) int {\n    if n <= 1 {\n        return ___          // base case\n    }\n    return n * fact(n-1)\n}\n"] = "func fact(n int) int {\n    if n <= 1 {\n        return ___          // základní případ\n    }\n    return n * fact(n-1)\n}\n",
